    out["vpcs"] = [{"id":v["VpcId"],"cidr":v["CidrBlock"]} for v in r.get("Vpcs",[])]
except Exception as e:
    out["vpcs_err"] = str(e)
try:
    r = await call_boto3(service_name="ec2", operation_name="DescribeSubnets", region_name="us-east-1")
    out["subnets"] = [{"id":s["SubnetId"],"az":s["AvailabilityZone"],"vpc":s["VpcId"],"pub":s.get("MapPublicIpOnLaunch")} for s in r.get("Subnets",[])]
except Exception as e:
    out["subnets_err"] = str(e)
try:
    r = await call_boto3(service_name="ec2", operation_name="DescribeInstances", region_name="us-east-1")
    out["instances"] = [{"id":i["InstanceId"],"state":i["State"]["Name"],"tags":i.get("Tags")} for res in r.get("Reservations",[]) for i in res["Instances"]]
except Exception as e:
    out["inst_err"] = str(e)
try:
    r = await call_boto3(service_name="elbv2", operation_name="DescribeLoadBalancers", region_name="us-east-1")
