const http = require('http');
const fs = require('fs');
const html = fs.readFileSync('/tmp/harness/siteb.html');
const tracker = fs.readFileSync('/tmp/harness/tracker.js');
const hits = [];
http.createServer((req, res) => {
  const url = req.url.split('?')[0];
  if (req.method === 'OPTIONS') {
    res.writeHead(204, {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'*','Access-Control-Allow-Methods':'GET, POST'});
    return res.end();
  }
  if (url === '/script.js') {
    hits.push({what:'script.js fetched', host:req.headers.host});
    res.writeHead(200, {'Content-Type':'application/javascript'});
    return res.end(tracker);
  }
  if (url === '/api/send') {
    let b = '';
    req.on('data', d => b += d);
    return req.on('end', () => {
      hits.push({what:'API_SEND', host:req.headers.host, body:b});
      res.writeHead(200, {'Content-Type':'application/json','Access-Control-Allow-Origin':'*'});
      res.end(JSON.stringify({cache:'tok'}));
    });
  }
  res.writeHead(200, {'Content-Type':'text/html'});
  res.end(html);
}).listen(8899, () => console.error('sink up'));
process.on('SIGTERM', () => { console.log(JSON.stringify(hits,null,1)); process.exit(0); });
setTimeout(() => { console.log(JSON.stringify(hits,null,1)); process.exit(0); }, 45000);
