const puppeteer=require('puppeteer');
(async()=>{
  // DEFAULT flags - no https-upgrade workaround, mimics a real headless visit
  const b=await puppeteer.launch({headless:true,args:['--no-sandbox','--disable-setuid-sandbox']});
  const p=await b.newPage();
  await p.setRequestInterception(true);
  let sent=null;
  p.on('request',r=>{
    if(r.url().includes('/api/send')){
      sent={url:r.url(),method:r.method(),body:r.postData()};
      console.log('[INTERCEPTED+ABORTED]',r.method(),r.url());
      return r.abort();           // nothing reaches the real umami
    }
    r.continue();
  });
  p.on('requestfailed',r=>{ if(!r.url().includes('/api/send')) console.log('[reqfailed]',r.url(),r.failure()&&r.failure().errorText);});
  p.on('response',r=>console.log('[resp]',r.status(),r.url()));
  const t0=Date.now();
  try{
    await p.goto('https://alcove-acscdb8a4d2.50-19-232-229.sslip.io/acspeed-verify-path',{waitUntil:'networkidle2',timeout:45000});
    console.log('[goto] OK in',Date.now()-t0,'ms');
  }catch(e){console.log('[goto] FAILED after',Date.now()-t0,'ms :',e.message);}
  const d=await p.evaluate(()=>{const s=document.querySelector('script[data-website-id]');
    return{rs:document.readyState,tag:!!s,src:s&&s.src,id:s&&s.getAttribute('data-website-id'),umami:typeof window.umami,href:location.href,proto:location.protocol};});
  console.log('[page]',JSON.stringify(d));
  await new Promise(r=>setTimeout(r,5000));
  console.log('[tracker-send]', sent?JSON.stringify(sent):'NONE - tracker never fired');
  await b.close();
})().catch(e=>{console.log('[fatal]',e.message);process.exit(1);});
EOF
